import { BaseComponent } from '../../core/base-component.js';
import { AuthService } from '../../core/auth.service.js';
import { apiRequest } from '../../core/api.js';

export class MenuLobbyComponent extends BaseComponent {
  constructor() {
    super('js/components/menu-lobby/menu-lobby.component.html');
  }

  async onInit() {
    this.renderLobby();

    // Re-render if hash changes while already on a lobby component
    this._onHashChange = () => {
      this.renderLobby();
    };
    window.addEventListener('hashchange', this._onHashChange);
  }

  disconnectedCallback() {
    if (this._onHashChange) window.removeEventListener('hashchange', this._onHashChange);
  }

  async renderLobby() {
    const currentHash = window.location.hash || '#/';

    let menuList = null;
    try {
      const menuStr = localStorage.getItem('user_menu');
      if (menuStr) {
        menuList = JSON.parse(menuStr);
      }
    } catch(e) {}

    if (!menuList || menuList.length === 0) {
      try {
        const response = await apiRequest('/me/menu', { method: 'GET' });
        menuList = response.data || response;
        localStorage.setItem('user_menu', JSON.stringify(menuList));
      } catch (err) {
        console.error('Error fetching menu for lobby:', err);
      }
    }

    const titleEl = this.querySelector('#lobby-title');
    const container = this.querySelector('#lobby-cards-container');

    if (!menuList || !titleEl || !container) return;

    // Remove query params from hash for matching
    const basePath = currentHash.split('?')[0];

    // Find the parent menu item that matches the current route
    const parentMenu = menuList.find(m => {
        const safeHref = m.ruta && m.ruta.startsWith('#') ? m.ruta : '#/';
        return safeHref === basePath;
    });

    if (!parentMenu) {
      titleEl.textContent = 'Menú no encontrado';
      container.innerHTML = '<div class="col-12"><p class="text-muted">No se encontraron opciones para esta sección.</p></div>';
      return;
    }

    titleEl.innerHTML = `<i class="${parentMenu.icono || ''} me-2 text-primary"></i> ${parentMenu.nombre}`;

    // Find children
    const children = menuList.filter(m => m.padre_id === parentMenu.id);

    if (children.length === 0) {
      container.innerHTML = '<div class="col-12"><p class="text-muted">No hay submenús disponibles.</p></div>';
      return;
    }

    let cardsHtml = '';
    children.forEach(child => {
        const safeHref = child.ruta && child.ruta.startsWith('#') ? child.ruta : '#/';

        cardsHtml += `
        <div class="col-12 col-md-6 col-lg-4">
          <a href="${safeHref}" class="text-decoration-none">
            <div class="card h-100 border-0 shadow-sm rounded-4 menu-lobby-card transition-all" style="cursor: pointer;">
              <div class="card-body p-4 d-flex align-items-center">
                <div class="icon-box bg-primary-soft text-primary rounded-3 d-flex align-items-center justify-content-center p-3 me-3" style="width: 60px; height: 60px; font-size: 24px;">
                  <i class="${child.icono || 'bi bi-dot'}"></i>
                </div>
                <div>
                  <h5 class="card-title fw-bold text-dark mb-1">${child.nombre}</h5>
                  <p class="card-text text-muted small mb-0">Acceder a ${child.nombre.toLowerCase()}</p>
                </div>
              </div>
            </div>
          </a>
        </div>
        `;
    });

    container.innerHTML = cardsHtml;

    // Add hover effect via JS dynamically or expect CSS to do it
    const cards = container.querySelectorAll('.menu-lobby-card');
    cards.forEach(card => {
        card.addEventListener('mouseenter', () => {
            card.classList.add('shadow');
            card.style.transform = 'translateY(-5px)';
        });
        card.addEventListener('mouseleave', () => {
            card.classList.remove('shadow');
            card.style.transform = 'translateY(0)';
        });
    });
  }
}

customElements.define('app-menu-lobby', MenuLobbyComponent);

import { BaseComponent } from '../../core/base-component.js';
import { apiRequest } from '../../core/api.js';
import { AuthService } from '../../core/auth.service.js';

export class SideBarComponent extends BaseComponent {
  constructor() {
    super('js/components/sidebar/sidebar.component.html');
    this.menuLoaded = false;
  }

  onInit() {
    this.renderSidebar();

    this._onHashChange = () => {
      this.renderSidebar();
      this.updateActiveLink();
    };
    window.addEventListener('hashchange', this._onHashChange);

    this._onAuthChange = () => {
      this.menuLoaded = false;
      this.renderSidebar();
    };
    window.addEventListener('auth-change', this._onAuthChange);

    this._onToggleSidebar = () => {
      const willHide = !this.classList.contains('collapsed');
      this.dataset.userHidden = willHide ? 'true' : 'false';
      this.classList.toggle('collapsed');
    };
    window.addEventListener('toggle-sidebar', this._onToggleSidebar);
  }

  disconnectedCallback() {
    if (this._onHashChange) window.removeEventListener('hashchange', this._onHashChange);
    if (this._onAuthChange) window.removeEventListener('auth-change', this._onAuthChange);

    if (this._onToggleSidebar) window.removeEventListener('toggle-sidebar', this._onToggleSidebar);
  }

  renderSidebar() {
    const sidebarContainer = this.firstElementChild;
    if (!sidebarContainer) return;

    const token = localStorage.getItem('access_token');
    const hash = window.location.hash || '#/';
    const userHidden = this.dataset.userHidden === 'true';

    if (!token || hash === '#/login') {
      this.dataset.userHidden = 'false';
      this.classList.add('d-none');
    } else if (userHidden) {
      this.classList.remove('d-none');
      this.classList.add('collapsed');
    } else {
      this.classList.remove('d-none');
      this.classList.remove('collapsed');
      if (!this.menuLoaded) {
        this.loadMenuData();
      }
      this.renderUserCard();
    }
  }

  async loadMenuData() {
    const container = this.querySelector('#dynamicMenuContainer');
    try {
      if (container) {
        container.innerHTML = `
          <div class="d-flex justify-content-center py-3" id="menuLoader">
            <div class="spinner-border spinner-border-sm text-primary" role="status">
              <span class="visually-hidden">
                Cargando...
              </span>
            </div>
          </div>
        `;
      }

      let menuList = null;
      try {
        const menuStr = localStorage.getItem('user_menu');
        if (menuStr) {
          menuList = JSON.parse(menuStr);
        }
      } catch (e) {}

      if (!menuList || menuList.length === 0) {
        const response = await apiRequest('/me/menu', { method: 'GET' });
        menuList = response.data || response;
        localStorage.setItem('user_menu', JSON.stringify(menuList));
      }

      const menuTree = this.buildMenuTree(menuList);

      this.renderMenuItems(menuTree);
      this.menuLoaded = true;
      this.updateActiveLink();
    } catch (error) {
      console.error('Error cargando el menú:', error);
      if (container)
        container.innerHTML = '<p class="text-danger small px-3">Error al cargar menú.</p>';
    }
  }

  buildMenuTree(menuList) {
    const tree = [];
    const lookup = {};

    const esc = (v) =>
      String(v ?? '').replace(
        /[&<>"']/g,
        (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]
      );
    const safeHref = (v) => {
      const s = String(v ?? '');
      return s.startsWith('#') ? s : '#/';
    };
    const safeClass = (v) => {
      const s = String(v ?? '').trim();
      return /^[a-z0-9\s-]+$/i.test(s) ? s : '';
    };
    menuList.forEach((item) => {
      lookup[item.id] = {
        ...item,
        nombre: esc(item.nombre),
        ruta: safeHref(item.ruta),
        icono: safeClass(item.icono),
        children: [],
      };
    });

    menuList.forEach((item) => {
      if (item.padre_id && lookup[item.padre_id]) {
        lookup[item.padre_id].children.push(lookup[item.id]);
      } else if (!item.padre_id) {
        tree.push(lookup[item.id]);
      }
    });

    return tree;
  }

  renderMenuItems(menuTree) {
    const container = this.querySelector('#dynamicMenuContainer');
    if (!container) return;

    let html = '';

    menuTree.forEach((menu) => {
      if (menu.children && menu.children.length > 0) {
        const collapseId = `collapse-menu-${menu.id}`;
        html += `
          <div class="nav-item">
              <a class="sidebar-link nav-link d-flex align-items-center gap-2 rounded-3 px-3 py-2 text-dark" href="${menu.ruta}">
                <i class="${menu.icono || 'bi bi-circle'} text-secondary"></i>
                <span>${menu.nombre}</span>
                <span class="ms-auto p-1 sidebar-toggle-btn" data-bs-toggle="collapse" data-bs-target="#${collapseId}" aria-expanded="false" style="cursor: pointer; z-index: 2; position: relative;">
                  <i class="bi bi-chevron-down small text-muted"></i>
                </span>
              </a>
            <div class="collapse ms-3" id="${collapseId}">
              <div class="nav flex-column gap-1 mt-1">
                ${menu.children
                  .map(
                    (child) => `
                  <a class="sidebar-link nav-link d-flex align-items-center gap-2 rounded-3 px-3 py-2 text-secondary" href="${child.ruta}">
                    <i class="${child.icono || 'bi bi-dot'} text-secondary"></i>
                    <span>${child.nombre}</span>
                  </a>
                `
                  )
                  .join('')}
              </div>
            </div>
          </div>
        `;
      } else {
        html += `
          <a class="sidebar-link nav-link d-flex align-items-center gap-2 rounded-3 px-3 py-2 text-dark" href="${menu.ruta}">
            <i class="${menu.icono || 'bi bi-circle'} text-secondary"></i>
            <span>${menu.nombre}</span>
          </a>
        `;
      }
    });

    container.innerHTML = html;

    // Prevent navigation when clicking the toggle arrow
    const toggleBtns = container.querySelectorAll('.sidebar-toggle-btn');
    toggleBtns.forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
      });
    });
  }

  updateActiveLink() {
    const currentHash = window.location.hash || '#/';
    const links = this.querySelectorAll('.sidebar-link');

    links.forEach((link) => {
      const href = link.getAttribute('href');

      if (href === currentHash && !link.hasAttribute('data-bs-toggle')) {
        link.classList.remove('text-dark', 'text-secondary', 'text-primary');
        link.classList.add('active', 'bg-primary', 'text-white');

        const icon = link.querySelector('i:first-child');
        if (icon) {
          icon.classList.remove('text-secondary');
          icon.classList.add('text-white');
        }

        const parentCollapse = link.closest('.collapse');
        if (parentCollapse) {
          parentCollapse.classList.add('show');

          // The toggle button that controls this collapse
          const parentBtn = document.querySelector(`[data-bs-target="#${parentCollapse.id}"]`);
          if (parentBtn) {
            const parentLink = parentBtn.closest('.sidebar-link');
            if (parentLink) {
              parentLink.classList.remove('text-dark');
              parentLink.classList.add('text-primary');
            }
          }
        }
      } else {
        link.classList.remove('active', 'bg-primary', 'text-white', 'text-primary');

        const icon = link.querySelector('i:first-child');
        if (icon) {
          icon.classList.remove('text-white');
          icon.classList.add('text-secondary');
        }

        if (link.closest('.collapse')) {
          link.classList.add('text-secondary');
        } else {
          link.classList.add('text-dark');
        }
      }
    });
  }

  renderUserCard() {
    // Deprecated: user profile info is shown in the top navbar dropdown.
  }
}

customElements.define('app-sidebar', SideBarComponent);

import { BaseComponent } from '../../core/base-component.js';
import { apiRequest } from '../../core/api.js';
import { AuthService } from '../../core/auth.service.js';
import { getSoftClass } from '../../shared/utils/badge-states.js';

export class DashboardComponent extends BaseComponent {
  constructor() {
    super('js/pages/dashboard/dashboard.component.html');
    this.map = null;
    this.clockInterval = null;
    this.mockMarkers = []; // to keep track of added markers
  }

  onInit() {
    console.log('DashboardComponent inicializado (onInit)');

    // 1. Iniciar reloj y fecha en vivo
    this.initClock();

    // 2. Personalizar Greeting
    this.initGreeting();

    // 3. Inicializar el Mapa en vivo (esperar un micro-tick para que el DOM esté listo)
    setTimeout(() => {
      this.initDashboardMap();
      this.loadDashboardData();
      this.initGrafanaDashboards();
    }, 50);

    // 4. Renderizar menú dinámico
    this.loadMenuData();
  }

  disconnectedCallback() {
    if (this.clockInterval) clearInterval(this.clockInterval);
    if (this.map) {
      this.map.remove();
      this.map = null;
    }
  }

  initGreeting() {
    const user = AuthService.getCurrentUser();
    if (user) {
      const greetingEl = this.querySelector('#dashboardGreeting');
      if (greetingEl) {
        greetingEl.textContent = `Bienvenido, ${user.name}`;
      }
    }
  }

  initClock() {
    const clockEl = this.querySelector('#liveClock');
    const dateEl = this.querySelector('#liveDate');

    const updateTime = () => {
      const now = new Date();
      if (clockEl) clockEl.textContent = now.toLocaleTimeString('es-EC', { hour12: false });
      if (dateEl)
        dateEl.textContent = now.toLocaleDateString('es-EC', {
          weekday: 'long',
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        });
    };

    updateTime();
    this.clockInterval = setInterval(updateTime, 1000);
  }

  async loadMenuData() {
    const container = this.querySelector('#dashboardMenuContainer');
    if (!container) return;

    try {
      let menuList = null;
      try {
        const menuStr = localStorage.getItem('user_menu');
        if (menuStr) {
          menuList = JSON.parse(menuStr);
        }
      } catch (e) {}

      if (!menuList || menuList.length === 0) {
        const response = await apiRequest('/me/menu', { method: 'GET' });
        menuList = response.data || response;
        localStorage.setItem('user_menu', JSON.stringify(menuList));
      }

      // Filtrar solo los menús de nivel superior
      const rootMenus = menuList.filter((item) => !item.padre_id);

      container.innerHTML = rootMenus
        .map(
          (menu) => `
        <div class="col-6 col-md-4 col-lg-3">
          <a href="${menu.ruta || '#/'}" class="card border border-light shadow-sm rounded-3 text-decoration-none stat-card-hover bg-white text-dark h-100">
            <div class="card-body p-3 d-flex align-items-center gap-3">
              <div class="bg-primary-soft rounded-3 p-2.5 text-primary d-inline-flex">
                <i class="${menu.icono || 'bi bi-grid'} fs-5"></i>
              </div>
              <div class="text-start">
                <span class="fw-bold small d-block" style="letter-spacing: -0.01em; line-height: 1.2;">${menu.nombre}</span>
              </div>
            </div>
          </a>
        </div>
      `
        )
        .join('');
    } catch (error) {
      console.error('Error cargando el menú del dashboard:', error);
      container.innerHTML = '<p class="text-danger">No se pudieron cargar las operaciones.</p>';
    }
  }

  async loadDashboardData() {
    try {
      const response = await apiRequest('/dashboard/stats');
      this.renderTopServices(response.servicios_mas_utilizados);
      this.renderRecentIncidents(response.recientes);
      this.updateMapMarkers(response.mapa_reportes);
    } catch (error) {
      console.error('Error cargando estadísticas del dashboard:', error);
    }
  }

  initGrafanaDashboards() {
    const container = this.querySelector('#grafanaKpisContainer');
    if (!container) return;

    const GRAFANA_BASE =
      window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'
        ? 'http://localhost:3000'
        : 'https://grafana.dihm-muertos.site';

    const user = AuthService.getCurrentUser();
    const instId = user && user.institucion_id ? user.institucion_id : '';
    const userId = user && user.id ? user.id : '';

    // Resolver rol por permisos o is_admin
    let role = 'Default';
    if (AuthService.isAdmin()) {
      role = 'Admin';
    } else if (AuthService.hasPermission('Ver Despacho de Incidencia')) {
      role = 'Supervisor';
    } else if (AuthService.hasPermission('Ver Kanban')) {
      role = 'Institucion';
    } else if (AuthService.hasPermission('Crear Incidencia')) {
      role = 'Ciudadano';
    }

    // URLs de dashboards completos por rol
    // Usamos el formato /d/{dashboard_uid}/ en lugar de /d-solo/ para incrustar el dashboard completo.
    // Usamos kiosk=1 para ocultar menús nativos de Grafana, u opcionalmente kiosk=tv si quieres conservar la barra de variables.
    const GRAFANA_DASHBOARDS = {
      Admin: `${GRAFANA_BASE}/d/adf7t6b/prod-incidents-admin?orgId=1&from=now-6h&to=now&timezone=browser&theme=light&refresh=10s&kiosk&embed=v2`,
      Supervisor: `${GRAFANA_BASE}/d/addt7bq/prod-incidents-supervisor?orgId=1&from=now-24h&to=now&timezone=browser&theme=light&refresh=5m&kiosk&embed=v2`,
      Institucion: `${GRAFANA_BASE}/d/ad6n9wt/prod-incidents-institucion?orgId=1&from=now-24h&to=now&timezone=browser&theme=light&refresh=10s&kiosk&embed=v2`,
      Ciudadano: `${GRAFANA_BASE}/d/adfds7b/prod-incidents-ciudadano?orgId=1&from=now-24h&to=now&timezone=browser&theme=light&refresh=30s&kiosk&embed=v2`,
    };

    // Si tuvieras un único dashboard unificado con pestañas (tabs) controladas por una variable 'dtab':
    // const GRAFANA_DASHBOARDS = {
    //   Admin: `${GRAFANA_BASE}/d/ad79j7w/incidents-dashboards?orgId=1&theme=light&kiosk=1&var-dtab=Admin`,
    //   Supervisor: `${GRAFANA_BASE}/d/ad79j7w/incidents-dashboards?orgId=1&theme=light&kiosk=1&var-dtab=Supervisor`,
    //   Institucion: `${GRAFANA_BASE}/d/ad79j7w/incidents-dashboards?orgId=1&theme=light&kiosk=1&var-dtab=Institucion&var-institucion_id=${instId}`,
    //   Ciudadano: `${GRAFANA_BASE}/d/ad79j7w/incidents-dashboards?orgId=1&theme=light&kiosk=1&var-dtab=Ciudadano&var-usuario_id=${userId}`,
    //   Default: `${GRAFANA_BASE}/d/ad79j7w/incidents-dashboards?orgId=1&theme=light&kiosk=1&var-dtab=General`,
    // };

    const dashboardUrl = GRAFANA_DASHBOARDS[role] || GRAFANA_DASHBOARDS['Default'];

    container.innerHTML = `
      <div class="w-100">
        <div class="card border-0 shadow-sm rounded-4 bg-transparent overflow-hidden" style="height: 100vh; max-height: 100vh;">
          <iframe 
            src="${dashboardUrl}" 
            width="100%" 
            height="100%" 
            style="border: none; display: block; width: 100%; height: 100%;" 
            frameborder="0"
            allowtransparency="true">
          </iframe>
        </div>
      </div>
    `;

    // Inyectar el gráfico de provincias si el usuario es Supervisor o Admin
    const provinciaChartContainer = this.querySelector('#provinciaChartContainer');
    const iframeProvincia = this.querySelector('#iframe-provincia-chart');
    if (provinciaChartContainer && iframeProvincia && (role === 'Supervisor' || role === 'Admin')) {
      provinciaChartContainer.style.display = 'block';
      iframeProvincia.src = `${GRAFANA_BASE}/d-solo/ad79j7w/incidents-dashboards?orgId=1&from=1783884717625&to=1783971317625&timezone=browser&dtab=Supervisor&var-custom0=&var-query0=&refresh=10s&theme=light&panelId=panel-25`;
    }
  }

  renderTopServices(services) {
    const container = this.querySelector('#dashboardTopServices');
    if (!container || !services) return;

    if (services.length === 0) {
      container.innerHTML = '<p class="text-muted small">No hay suficientes datos registrados.</p>';
      return;
    }

    container.innerHTML = services
      .map(
        (service) => `
      <div>
        <div class="d-flex justify-content-between text-secondary small fw-bold mb-1">
          <span>${service.nombre}</span>
          <span class="text-dark">${service.porcentaje}%</span>
        </div>
        <div class="progress rounded-pill" style="height: 8px;">
          <div class="progress-bar bg-${service.color}" role="progressbar" style="width: ${service.porcentaje}%" aria-valuenow="${service.porcentaje}" aria-valuemin="0" aria-valuemax="100"></div>
        </div>
      </div>
    `
      )
      .join('');
  }

  initDashboardMap() {
    const mapContainer = this.querySelector('#dashboardMap');
    if (!mapContainer) return;

    const defaultLat = -3.99313;
    const defaultLng = -79.20422;

    this.map = L.map(mapContainer, {
      center: [defaultLat, defaultLng],
      zoom: 14,
      zoomControl: false,
    });

    L.control.zoom({ position: 'bottomright' }).addTo(this.map);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
      attribution: '&copy; OpenStreetMap &copy; CARTO',
      subdomains: 'abcd',
      maxZoom: 20,
    }).addTo(this.map);
  }

  updateMapMarkers(markersData) {
    if (!this.map || !markersData) return;

    markersData.forEach((inc) => {
      const marker = L.circleMarker([inc.lat, inc.lng], {
        radius: 10,
        fillColor: '#3b82f6',
        color: '#ffffff',
        weight: 2.5,
        fillOpacity: 0.95,
      }).addTo(this.map);

      marker.bindPopup(`
        <div style="font-family: 'Outfit', sans-serif;">
          <span class="badge mb-1 bg-primary-soft text-primary" style="border: 1px solid #3b82f640; font-weight: bold;">
            ${inc.categoria}
          </span>
          <h6 class="fw-bold text-dark m-0" style="font-size: 0.9rem;">${inc.titulo || 'Sin descripción'}</h6>
        </div>
      `);
      this.mockMarkers.push(marker);
    });

    // Enfoque en la incidencia más reciente
    const mostRecent = markersData[0];
    if (mostRecent && mostRecent.lat && mostRecent.lng) {
      this.map.setView([mostRecent.lat, mostRecent.lng], 15);
    }
  }

  renderRecentIncidents(incidents) {
    const container = this.querySelector('#recentIncidentsList');
    if (!container || !incidents) return;

    if (incidents.length === 0) {
      container.innerHTML =
        '<tr><td colspan="7" class="text-center text-muted py-4">No hay reportes recientes.</td></tr>';
      return;
    }

    container.innerHTML = incidents
      .map((inc) => {
        const estadoClass = getSoftClass(inc.estado);

        return `
        <tr data-id="${inc.id}" style="cursor: pointer;">
          <td><span class="fw-bold text-dark">INC-${inc.id.toString().padStart(4, '0')}</span></td>
          <td>
            <div class="fw-semibold text-dark text-truncate" style="max-width: 280px;" title="${inc.descripcion || ''}">${inc.descripcion || 'Sin descripción'}</div>
          </td>
          <td>
            <span class="text-secondary d-flex align-items-center gap-1.5">
              <i class="bi bi-tag-fill text-primary small"></i> ${inc.categoria}
            </span>
          </td>
          <td><span class="text-secondary">${inc.ubicacion}</span></td>
          <td>
            <span class="badge px-2.5 py-1.5 rounded-pill fw-bold bg-primary-soft text-primary" style="font-size: 0.75rem;">
              ${inc.prioridad}
            </span>
          </td>
          <td>
            <span class="badge px-2.5 py-1.5 rounded-pill fw-bold border ${estadoClass}" style="font-size: 0.75rem;">
              ${inc.estado}
            </span>
          </td>
          <td class="text-muted">${inc.reportado}</td>
        </tr>
      `;
      })
      .join('');

    // Dblclick listener para redirección a edición
    const rows = container.querySelectorAll('tr[data-id]');
    rows.forEach((row) => {
      row.addEventListener('dblclick', () => {
        const id = row.getAttribute('data-id');
        window.location.hash = `#/incidencias/form?id=${id}`;
      });
    });
  }
}

